select id, full_name, email, dept_id, job_title, salary, hire_date, is_remote, round(salary / sum(salary) over (partition by dept_id), 4) as salary_share, percent_rank() over (partition by year(hire_date), dept_id order by salary) as salary_percent_rank, last_value(job_title, true) over (order by hire_date, id rows between unbounded preceding and current row) as last_known_job_title from employees
